        def self.match(suffix)
          node = TRIE
          best = nil
          best_len = 0
          suffix.each_char.with_index do |char, index|
            node = node[char]
            break unless node
            if (value = node[:v])
              best = value
              best_len = index + 1
            end
          end
          return unless best

          [best_len, best[0], best[1]]
        end
      end
    end
